#!/usr/bin/env python3
# Some portions generated by Codex. Independent fresh-server means; all requests retained.
import pathlib,json,statistics,math,re
r=pathlib.Path(__file__).resolve().parent;forks=[];metrics=['headersMs','firstRowMs','batchMs','endMs','eofMs']
for d in sorted((r/'runs').glob('matched-*')):
 manifest=json.loads((d/'manifest.json').read_text());assert manifest['status']=='passed',d
 allrows=[]
 for i in range(-60,30):
  x=json.loads((d/f'query-{i}.json').read_text());assert x['rows']==100000 and int(x['terminal']['total-result-count'])==100000
  allrows.append(x)
 rows=allrows[60:];pauses=[float(x) for x in re.findall(r'Pause[^\n]*? ([0-9.]+)ms$',(d/'gc.log').read_text(),re.M)]
 forks.append({'name':d.name,'arm':manifest['arm'],'means':{k:statistics.mean(x[k] for x in rows) for k in metrics},'rangeEofMs':[min(x['eofMs'] for x in rows),max(x['eofMs'] for x in rows)],'byIndex':{k:[x[k] for x in rows] for k in metrics},'coldFirstQuery':{k:allrows[0][k] for k in metrics},'wholeJvmGc':{'count':len(pauses),'totalMs':sum(pauses),'maxMs':max(pauses,default=0)},'heapBeforeMean':statistics.mean(x['before']['heapUsed'] for x in rows),'heapAfterMean':statistics.mean(x['after']['heapUsed'] for x in rows)})
assert len(forks)==16,len(forks)
arms={}
for arm in ['base','depth','resource','both']:
 ff=[f for f in forks if f['arm']==arm];assert len(ff)==4
 arms[arm]={'means':{k:statistics.mean(f['means'][k] for f in ff) for k in metrics},'forkRangeEofMs':[min(f['means']['eofMs'] for f in ff),max(f['means']['eofMs'] for f in ff)],'measuredIndexMeanEofMs':[statistics.mean(f['byIndex']['eofMs'][i] for f in ff) for i in range(30)]}
blocks=[]
for i in range(0,16,4):
 b={f['arm']:f['means'] for f in forks[i:i+4]};assert len(b)==4
 blocks.append(b)
contrasts={}
for numerator,denominator in [('both','depth'),('resource','base'),('depth','base'),('both','base'),('both','resource'),('resource','depth')]:
 out={}
 for k in metrics:
  a,b=arms[denominator]['means'][k],arms[numerator]['means'][k]
  xs=[math.log(x[numerator][k]/x[denominator][k]) for x in blocks]
  m=statistics.mean(xs);e=3.1824463*statistics.stdev(xs)/2
  out[k]={'latencyReductionPercent':100*(1-b/a),'throughputChangePercent':100*(a/b-1),'pairedReductionPercent':[100*(1-math.exp(x)) for x in xs],'descriptive95ReductionInterval':[100*(1-math.exp(m+e)),100*(1-math.exp(m-e))]}
 contrasts[numerator+'-versus-'+denominator]=out
interaction={}
for k in metrics:
 xs=[math.log(x['both'][k]*x['base'][k]/(x['depth'][k]*x['resource'][k])) for x in blocks]
 m=statistics.mean(xs);e=3.1824463*statistics.stdev(xs)/2
 interaction[k]={'pairedLogRatios':xs,'geometricInteractionRatio':math.exp(m),'descriptive95RatioInterval':[math.exp(m-e),math.exp(m+e)],'interpretation':'ratio below one indicates supermultiplicative latency reduction; descriptive unadjusted evidence only'}
for arm in arms:
 ix=arms[arm]['measuredIndexMeanEofMs'];arms[arm]['measuredThirdMeanEofMs']=[statistics.mean(ix[i:i+10]) for i in (0,10,20)]
print(json.dumps({'scope':'Actual Workbench HTTP/NDJSON full100k window; no browser render/concurrent QPS claim','arms':arms,'contrasts':contrasts,'interaction':interaction,'forks':forks},indent=2))
